def solve(text, required):
    if not required:
        return 0
    required = set(required)
    if not text:
        return -1
    for i in range(len(text)):
        seen = set()
        for j in range(i, len(text)):
            seen.add(text[j])
            if seen == required:
                return j - i + 1
    return -1
```

