def solve(graph, start, end):
    if start == end:
        return 0
    seen = {start}
    queue = [start]
    for node in queue:
        for neighbor in graph.get(node, ()):
            if neighbor == end:
                return 1
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append(neighbor)
    return -1
